from taf.collectors.core.entities.managed_admin_connection import ManagedSbtsAdminConnection
from .factory import ReusableFactory


class ManagedSbtsAdminConnectionFactory(ReusableFactory):
    _product_class = ManagedSbtsAdminConnection
    _mandatory_parameters = {"admin_connection_params"}
    _existing_product_objects = {}

    @staticmethod
    def _create_unique_key (resulting_arguments):
        reuse = resulting_arguments["admin_connection_params"].get("reuse", True)
        unique_key = tuple(
            sorted(
                (k, d[k])
                for k in ("user", "host", "port", "remote_host", "release")
                if k in (d := resulting_arguments["admin_connection_params"])))
        return unique_key, reuse
